}

/** Toolbar: search + filter row + actions (reference `dtb-fbar` / `dtb-frow`). Press "/" to focus the search (when the hint is shown). */
export function AdminFilterBar({ search, onSearchChange, searchPlaceholder = "Tìm kiếm…", onRefresh, filters, actions, beforeRefresh, hideKbd, hideSearch, refreshIcon, onReset, className }: {
  search?: string; onSearchChange?: (v: string) => void; searchPlaceholder?: string; onRefresh?: () => void; filters?: React.ReactNode; actions?: React.ReactNode
  /** Icon buttons placed before the refresh button (the first icon button takes the `ml-auto`). */
  beforeRefresh?: React.ReactNode
  /** Reference screens without the "/" hint in the search box. */
  hideKbd?: boolean
  /** Toolbars without a search box (e.g. the HR sync history). */
  hideSearch?: boolean
  /** Some reference screens use the clockwise "rotate-cw" icon instead of "refresh-cw". */
  refreshIcon?: React.ReactNode; className?: string
  /** RIS: nút "Xoá bộ lọc" trong drawer bộ lọc nâng cao. */
  onReset?: () => void
}) {
  const input = React.useRef<HTMLInputElement>(null)
  React.useEffect(() => {
    if (hideKbd || hideSearch) return
    const onKey = (e: KeyboardEvent) => {
      if (e.key !== "/" || e.ctrlKey || e.metaKey || e.altKey || e.defaultPrevented) return
      const t = e.target as HTMLElement | null
      if (t && (t.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName) || t.closest("[role=dialog],[role=menu],[role=listbox]"))) return
      e.preventDefault()
      input.current?.focus()
    }
    document.addEventListener("keydown", onKey)
    return () => document.removeEventListener("keydown", onKey)
  }, [hideKbd, hideSearch])
  // RIS: thanh lọc luôn một hàng; bộ lọc không vừa chỗ chuyển vào drawer "Bộ lọc nâng cao".
  return (
    <ResponsiveFilterRow
      frame={cn("-mx-(--page-bleed-x) -mt-(--page-bleed-t) flex-none border-b bg-card px-[calc(var(--page-bleed-x,0px)+--spacing(2.5))] py-[9px]", className)}
      onReset={onReset}
      search={hideSearch ? undefined : <div className="relative flex h-9 coarse:h-11 min-w-[140px] max-w-[420px] flex-[1_1_260px] items-center gap-[9px] rounded-md border bg-card px-[11px] focus-within:border-primary focus-within:shadow-focus-field max-[900px]:max-w-none max-[900px]:min-w-0 max-[900px]:flex-auto overflow-hidden">
          <Search aria-hidden strokeWidth={2.2} className="size-4 flex-none text-subtle-foreground" />
          <input ref={input} type="text" value={search ?? ""} onChange={(e) => onSearchChange?.(e.target.value)} placeholder={searchPlaceholder} aria-label={searchPlaceholder} className="min-w-0 flex-1 border-0 bg-transparent text-sm text-foreground outline-0 placeholder:text-subtle-foreground" />
          {!hideKbd && <Kbd aria-hidden className="max-sm:hidden">/</Kbd>}
        </div>}
      filters={toFilterItems(filters, (el) => el.type === AdminSegmented)}
      actions={<>
        {beforeRefresh}
        {onRefresh && <Button variant="outline" size="toolbar-icon" aria-label="Làm mới" title="Tải lại" className="text-muted-foreground hover:text-foreground" onClick={onRefresh}>{refreshIcon ?? <RefreshCw />}</Button>}
        {actions}
      </>}
    />
  )
}

